SELECT A.SEQNO seqno, A.SEC_TYPE_MODEL secTypeModel, A.SEC_DETAIL_TYPE_MODEL secDetailTypeModel, A.FINPROD_ID finprodId, A.FINPROD_NAME finprodName, A.GRADE_SOURCE gradeSource, A.GRADE_RESULT gradeResult, A.BASEDATE basedate, A.SPREAD spread, A.SPREAD_ADJ spreadAdj, A.B_FULLPRICE bFullprice, A.B_QTY bQty, A.MOD_METHOD modMethod
,A.CURVE_CODE curveCode, NVL(m.CURVE_NAME, A.CURVE_CODE) curveName, A.CURVE_DATE curveDate
FROM MOD_RISK_PREMIUM A left join MOD_CURVE_MAPPING m on A.CURVE_CODE = m.CURVE_CODE WHERE A.SEQNO = #{seqNo}

mapper.update:
update MOD_RISK_PREMIUM
set SPREAD_ADJ = #{spreadAdj,jdbcType=DECIMAL},
	UPDATE_USER = #{updateUser,jdbcType=VARCHAR},
	UPDATE_TIME = #{updateTime,jdbcType=TIMESTAMP}
where SEQNO = #{seqno,jdbcType=VARCHAR}
